<script setup>
import { computed, ref } from 'vue'
const items = [
  { id: 'svg', tag: 'svg', title: 'Контейнер SVG', text: 'Задаёт область рисунка и систему координат через `viewBox`.', card: 'svg-vector', mdn: 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/svg' },
  { id: 'g', tag: 'g', title: 'Группа', text: 'Объединяет элементы схемы; стили и трансформации наследуются потомками.', card: 'svg-group', mdn: 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/g' },
  { id: 'path', tag: 'path', title: 'Маршрут', text: 'Рисует линию маршрута с помощью атрибута `d`.', card: 'svg-path', mdn: 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/path' },
  { id: 'circle', tag: 'circle', title: 'Точка', text: 'Круговой узел схемы с координатами `cx`, `cy` и радиусом `r`.', card: 'svg-vector', mdn: 'https://developer.mozilla.org/en-US/docs/Web/SVG/Reference/Element/circle' },
]
const active = ref(null)
const selected = computed(() => items.find((item) => item.id === active.value))
function select(id) { active.value = active.value === id ? null : id }
</script>

<template><div class="flex flex-col gap-6"><header><h1 class="text-2xl font-extrabold text-slate-900">Справочник SVG</h1><p class="mt-1 text-slate-500">Интерактивная мини-схема: выберите тег в коде, на рисунке или в карточке.</p></header><div v-if="selected" class="sticky top-20 z-10 flex items-center justify-between gap-3 rounded-xl bg-slate-900 px-4 py-3 text-sm text-white shadow-lg"><code>&lt;{{ selected.tag }}&gt;</code><button class="rounded-lg bg-white/10 px-3 py-1.5 font-semibold hover:bg-white/20" @click="active = null">Снять выделение</button></div><section class="card p-5"><svg viewBox="0 0 560 200" class="w-full" role="img" aria-label="Схема маршрута с тремя остановками"><g @click="select('g')" class="cursor-pointer"><path d="M70 140 C160 30 270 180 470 60" fill="none" stroke="currentColor" stroke-width="8" class="text-slate-300" :class="active === 'path' || active === 'g' || active === 'svg' ? 'text-brand-500' : ''"/><circle v-for="(point, index) in [[70,140],[270,110],[470,60]]" :key="index" :cx="point[0]" :cy="point[1]" r="18" class="cursor-pointer fill-white stroke-slate-700" :class="active === 'circle' || active === 'g' || active === 'svg' ? 'stroke-brand-500' : ''" stroke-width="6" @click.stop="select('circle')"/></g></svg><div class="mt-4 rounded-xl bg-slate-950 p-4 font-mono text-sm leading-7 text-slate-300"><button @click="select('svg')" :class="active === 'svg' ? 'rounded bg-slate-700' : ''">&lt;svg viewBox="0 0 560 200"&gt;</button><br><span class="pl-4"><button @click="select('g')" :class="active === 'g' ? 'rounded bg-slate-700' : ''">&lt;g&gt;</button></span><br><span class="pl-8"><button @click="select('path')" :class="active === 'path' ? 'rounded bg-slate-700' : ''">&lt;path d="…" /&gt;</button></span><br><span class="pl-8"><button @click="select('circle')" :class="active === 'circle' ? 'rounded bg-slate-700' : ''">&lt;circle cx="…" cy="…" r="18" /&gt;</button></span><br><span class="pl-4">&lt;/g&gt;</span><br>&lt;/svg&gt;</div></section><section class="flex flex-col gap-3"><article v-for="item in items" :key="item.id" class="card overflow-hidden"><button class="flex w-full items-center justify-between px-5 py-4 text-left" @click="select(item.id)"><span><code class="rounded bg-slate-100 px-2 py-1 font-mono text-sm text-fuchsia-700">&lt;{{ item.tag }}&gt;</code><span class="ml-3 font-semibold text-slate-800">{{ item.title }}</span></span><span class="material-symbols-rounded text-slate-400">{{ active === item.id ? 'expand_less' : 'expand_more' }}</span></button><div v-if="active === item.id" class="border-t border-slate-100 px-5 py-4"><p class="text-sm text-slate-600">{{ item.text }}</p><p class="mt-3 text-sm text-slate-500">Связанная карточка: <code>{{ item.card }}</code></p><a class="mt-4 inline-flex text-sm font-semibold text-brand-700 hover:underline" :href="item.mdn" target="_blank" rel="noreferrer">Подробнее на MDN Web Docs →</a></div></article></section></div></template>
